```r
# ============================================================
# MR-PRESSO sensitivity analysis
# ============================================================
#
# Purpose:
#   Assess horizontal pleiotropy and identify potential
#   pleiotropic outliers using MR-PRESSO.
#
# Input:
#   Harmonized MR datasets generated by 02_Univariable_MR.
#
# Output:
#   1. MR_PRESSO_main_results.csv
#   2. MR_PRESSO_global_test.csv
#   3. MR_PRESSO_outlier_test.csv
#   4. MR_PRESSO_distortion_test.csv
#
# Important:
#   - The same harmonized MR datasets used for the primary
#     random-effects IVW analyses are used here.
#   - No independent SNP selection is performed.
#   - No LD clumping is performed.
#   - No independent harmonisation is performed.
#   - MR-PRESSO is performed only when at least 4 valid SNPs
#     are available.
#   - MR-PRESSO is a sensitivity analysis and does not replace
#     the primary random-effects IVW estimate.
#
# Software:
#   R >= 4.5.0
#   TwoSampleMR 0.6.29
#   MRPRESSO 1.0
#
# ============================================================


# ------------------------------------------------------------
# 1. Packages
# ------------------------------------------------------------

required_packages <- c(
  "here",
  "MRPRESSO",
  "readr",
  "dplyr"
)

missing_packages <- required_packages[
  !vapply(required_packages, requireNamespace, logical(1), quietly = TRUE)
]

if (length(missing_packages) > 0) {
  stop(
    "The following required packages are not installed: ",
    paste(missing_packages, collapse = ", "),
    call. = FALSE
  )
}

library(here)
library(MRPRESSO)
library(readr)
library(dplyr)


# ------------------------------------------------------------
# 2. Project directories
# ------------------------------------------------------------

harmonized_dir <- here::here(
  "results",
  "primary_MR",
  "harmonized"
)

output_dir <- here::here(
  "results",
  "sensitivity",
  "MR_PRESSO"
)

dir.create(
  output_dir,
  recursive = TRUE,
  showWarnings = FALSE
)


# ------------------------------------------------------------
# 3. Input files
# ------------------------------------------------------------
#
# These must be the SAME harmonized datasets used by the
# corresponding primary MR analyses.
#
# Replace the entries below with the exact filenames generated
# by 02_Univariable_MR.
# ------------------------------------------------------------

harmonized_files <- c(
  # "CRP_on_VaD_overall.csv",
  # "CRP_on_VaD_undefined.csv",
  # "CRP_on_VaD_subcortical.csv",
  # "CRP_on_VaD_multi_infarct.csv",
  # "CRP_on_VaD_mixed.csv"
)

if (length(harmonized_files) == 0) {
  stop(
    paste0(
      "No harmonized MR input files have been specified.\n",
      "Please populate 'harmonized_files' with the exact output ",
      "files generated by 02_Univariable_MR."
    ),
    call. = FALSE
  )
}

harmonized_paths <- file.path(
  harmonized_dir,
  harmonized_files
)

missing_files <- harmonized_paths[
  !file.exists(harmonized_paths)
]

if (length(missing_files) > 0) {
  stop(
    "The following harmonized MR input files do not exist:\n",
    paste(missing_files, collapse = "\n"),
    call. = FALSE
  )
}


# ------------------------------------------------------------
# 4. Helper function: validate harmonized MR dataset
# ------------------------------------------------------------

validate_harmonized_data <- function(dat, file_name) {
  
  required_columns <- c(
    "SNP",
    "beta.exposure",
    "se.exposure",
    "beta.outcome",
    "se.outcome",
    "mr_keep"
  )
  
  missing_columns <- setdiff(
    required_columns,
    names(dat)
  )
  
  if (length(missing_columns) > 0) {
    stop(
      paste0(
        "Input file '", file_name,
        "' is missing required columns: ",
        paste(missing_columns, collapse = ", ")
      ),
      call. = FALSE
    )
  }
  
  dat <- dat %>%
    filter(
      !is.na(SNP),
      !is.na(beta.exposure),
      !is.na(se.exposure),
      !is.na(beta.outcome),
      !is.na(se.outcome),
      mr_keep == TRUE
    )
  
  if (nrow(dat) < 4) {
    return(NULL)
  }
  
  dat
}


# ------------------------------------------------------------
# 5. Helper function: extract analysis identifiers
# ------------------------------------------------------------

get_analysis_info <- function(dat, input_file) {
  
  tibble(
    id.exposure = if ("id.exposure" %in% names(dat)) {
      unique(dat$id.exposure)[1]
    } else {
      NA_character_
    },
    id.outcome = if ("id.outcome" %in% names(dat)) {
      unique(dat$id.outcome)[1]
    } else {
      NA_character_
    },
    exposure = if ("exposure" %in% names(dat)) {
      unique(dat$exposure)[1]
    } else {
      NA_character_
    },
    outcome = if ("outcome" %in% names(dat)) {
      unique(dat$outcome)[1]
    } else {
      NA_character_
    },
    input_file = basename(input_file),
    nsnp = nrow(dat)
  )
}


# ------------------------------------------------------------
# 6. Helper function: run MR-PRESSO
# ------------------------------------------------------------

run_mr_presso_analysis <- function(dat) {
  
  if (nrow(dat) < 4) {
    return(NULL)
  }
  
  presso_input <- data.frame(
    beta.exposure = dat$beta.exposure,
    beta.outcome = dat$beta.outcome,
    se.exposure = dat$se.exposure,
    se.outcome = dat$se.outcome
  )
  
  result <- tryCatch(
    {
      MRPRESSO::mr_presso(
        BetaOutcome = "beta.outcome",
        BetaExposure = "beta.exposure",
        SdOutcome = "se.outcome",
        SdExposure = "se.exposure",
        OUTLIERtest = TRUE,
        DISTORTIONtest = TRUE,
        data = presso_input,
        NbDistribution = 1000,
        SignifThreshold = 0.05
      )
    },
    error = function(e) {
      
      warning(
        "MR-PRESSO failed: ",
        conditionMessage(e),
        call. = FALSE
      )
      
      NULL
    }
  )
  
  result
}


# ------------------------------------------------------------
# 7. Helper function: extract main MR-PRESSO results
# ------------------------------------------------------------

extract_main_results <- function(
    presso_result,
    analysis_info) {
  
  if (is.null(presso_result)) {
    return(NULL)
  }
  
  main_results <- presso_result$`Main MR results`
  
  if (is.null(main_results) ||
      nrow(main_results) == 0) {
    return(NULL)
  }
  
  result <- as.data.frame(main_results)
  
  result <- result %>%
    mutate(
      analysis_info
    )
  
  result
}


# ------------------------------------------------------------
# 8. Helper function: extract global test
# ------------------------------------------------------------

extract_global_test <- function(
    presso_result,
    analysis_info) {
  
  if (is.null(presso_result)) {
    return(NULL)
  }
  
  global_test <- presso_result$`MR-PRESSO results`$`Global Test`
  
  if (is.null(global_test)) {
    return(NULL)
  }
  
  result <- data.frame(
    RSSobs = global_test$RSSobs,
    Pvalue = global_test$Pvalue
  )
  
  result %>%
    mutate(
      analysis_info
    )
}


# ------------------------------------------------------------
# 9. Helper function: extract outlier test
# ------------------------------------------------------------

extract_outlier_test <- function(
    presso_result,
    analysis_info) {
  
  if (is.null(presso_result)) {
    return(NULL)
  }
  
  outlier_test <- presso_result$`MR-PRESSO results`$`Outlier Test`
  
  if (is.null(outlier_test)) {
    return(NULL)
  }
  
  result <- as.data.frame(outlier_test)
  
  result %>%
    mutate(
      analysis_info
    )
}


# ------------------------------------------------------------
# 10. Helper function: extract distortion test
# ------------------------------------------------------------

extract_distortion_test <- function(
    presso_result,
    analysis_info) {
  
  if (is.null(presso_result)) {
    return(NULL)
  }
  
  distortion_test <-
    presso_result$`MR-PRESSO results`$`Distortion Test`
  
  if (is.null(distortion_test)) {
    return(NULL)
  }
  
  result <- data.frame(
    Outliers_Indices =
      distortion_test$`Outliers Indices`,
    Distortion_Coefficient =
      distortion_test$`Distortion Coefficient`,
    Pvalue =
      distortion_test$Pvalue
  )
  
  result %>%
    mutate(
      analysis_info
    )
}


# ------------------------------------------------------------
# 11. Run MR-PRESSO
# ------------------------------------------------------------

main_results_list <- list()
global_results_list <- list()
outlier_results_list <- list()
distortion_results_list <- list()

for (i in seq_along(harmonized_paths)) {
  
  input_file <- harmonized_paths[i]
  input_name <- basename(input_file)
  
  message(
    "Processing MR-PRESSO: ",
    input_name
  )
  
  dat <- readr::read_csv(
    input_file,
    show_col_types = FALSE
  )
  
  dat <- validate_harmonized_data(
    dat = dat,
    file_name = input_name
  )
  
  if (is.null(dat)) {
    
    message(
      "  Fewer than 4 valid SNPs. MR-PRESSO skipped."
    )
    
    next
  }
  
  message(
    "  Valid SNPs: ",
    nrow(dat)
  )
  
  analysis_info <- get_analysis_info(
    dat = dat,
    input_file = input_file
  )
  
  presso_result <- run_mr_presso_analysis(
    dat = dat
  )
  
  if (is.null(presso_result)) {
    message(
      "  MR-PRESSO failed or returned no result."
    )
    next
  }
  
  # ----------------------------------------------------------
  # Main MR results
  # ----------------------------------------------------------
  
  main_result <- extract_main_results(
    presso_result = presso_result,
    analysis_info = analysis_info
  )
  
  if (!is.null(main_result)) {
    main_results_list[[length(main_results_list) + 1]] <-
      main_result
  }
  
  
  # ----------------------------------------------------------
  # Global test
  # ----------------------------------------------------------
  
  global_result <- extract_global_test(
    presso_result = presso_result,
    analysis_info = analysis_info
  )
  
  if (!is.null(global_result)) {
    global_results_list[[length(global_results_list) + 1]] <-
      global_result
  }
  
  
  # ----------------------------------------------------------
  # Outlier test
  # ----------------------------------------------------------
  
  outlier_result <- extract_outlier_test(
    presso_result = presso_result,
    analysis_info = analysis_info
  )
  
  if (!is.null(outlier_result)) {
    outlier_results_list[[length(outlier_results_list) + 1]] <-
      outlier_result
  }
  
  
  # ----------------------------------------------------------
  # Distortion test
  # ----------------------------------------------------------
  
  distortion_result <- extract_distortion_test(
    presso_result = presso_result,
    analysis_info = analysis_info
  )
  
  if (!is.null(distortion_result)) {
    distortion_results_list[[length(distortion_results_list) + 1]] <-
      distortion_result
  }
}


# ------------------------------------------------------------
# 12. Combine results
# ------------------------------------------------------------

main_results <- if (length(main_results_list) > 0) {
  bind_rows(main_results_list)
} else {
  tibble()
}

global_results <- if (length(global_results_list) > 0) {
  bind_rows(global_results_list)
} else {
  tibble()
}

outlier_results <- if (length(outlier_results_list) > 0) {
  bind_rows(outlier_results_list)
} else {
  tibble()
}

distortion_results <- if (length(distortion_results_list) > 0) {
  bind_rows(distortion_results_list)
} else {
  tibble()
}


# ------------------------------------------------------------
# 13. Save results
# ------------------------------------------------------------

readr::write_csv(
  main_results,
  file.path(
    output_dir,
    "MR_PRESSO_main_results.csv"
  ),
  na = ""
)

readr::write_csv(
  global_results,
  file.path(
    output_dir,
    "MR_PRESSO_global_test.csv"
  ),
  na = ""
)

readr::write_csv(
  outlier_results,
  file.path(
    output_dir,
    "MR_PRESSO_outlier_test.csv"
  ),
  na = ""
)

readr::write_csv(
  distortion_results,
  file.path(
    output_dir,
    "MR_PRESSO_distortion_test.csv"
  ),
  na = ""
)


# ------------------------------------------------------------
# 14. Completion message
# ------------------------------------------------------------

message(
  "\nMR-PRESSO sensitivity analyses completed."
)

message(
  "Results saved to: ",
  output_dir
)
```
